    "description": "今天（11月10日）凌晨，厦金大桥（厦门段）海上主线桥顺利合龙，标志着厦金大桥（厦门段）海上主线桥主体结构建设完成，项目进入通车前的收尾阶段。厦金大桥（厦门段）全长约19.6公里，包括海上主线桥、支线桥和陆地隧道等工程。其中主线全长17.34公里，跨海段为双向8车道，设计时速100公里。预计今年底海上主线桥建成通车后，厦门本岛至大嶝岛的通行时间将进一步缩短，实现本岛至翔安国际机场通行效率大幅提升。（央视新闻）",
