    "description": "天下难事，必作于易；天下大事，必作于细。干事创业，贵在落实，成败关键在于落细。对青年干部而言，抓细，是“致广大而尽精微”的科学方法，是破除落实梗阻、厚植为民根基的必修课。以细为要、以实为本，在精微处下功夫，就能把宏伟蓝图转化为看得见、摸得着的发展实效。",
    "content": "天下难事，必作于易；天下大事，必作于细。干事创业，贵在落实，成败关键在于落细。对青年干部而言，抓细，是“致广大而尽精微”的科学方法，是破除落实梗阻、厚植为民根基的必修课。以细为要、以实为本，在精微处下功夫，就能把宏伟蓝图转化为看得见、摸得着的发展实效。"
