    "description": "主力资金早间净流入传媒、机械设备、汽车、计算机、电力设备、家用电器等板块，净流出非银金融、石油石化、通信、医药生物、煤炭等板块。具体到个股来看，华策影视、龙江交通、冰山冷热获净流入14.53亿元、7.62亿元、6.87亿元。净流出方面，药明康德、长鑫科技、新易盛遭抛售8.13亿元、7.69亿元、5.04亿元。（第一财经）",
