    "description": "1928年，22岁的美国青年埃德加·斯诺抵达上海。出发前，他给家人留下一封信，写道：“此刻的幸福就是：旅行！冒险！体验！”原本只打算停留六周的他，最终与中国结下了跨越四十余年的情缘。 2026年是中国工农红军长征胜利90周年，也是斯诺初次访问陕北90周年。澎湃新闻获悉，上海革命历史博物馆启动系列纪念活动，“红星·漫记·长征路——埃德加·斯诺与中国”主题展同于11月10日起向公众开放。展览汇集近200件展品，包括不同文字版本的《红星照耀中…",
    "content": "1928年，22岁的美国青年埃德加·斯诺抵达上海。出发前，他给家人留下一封信，写道：“此刻的幸福就是：旅行！冒险！体验！”原本只打算停留六周的他，最终与中国结下了跨越四十余年的情缘。 2026年是中国工农红军长征胜利90周年，也是斯诺初次访问陕北90周年。澎湃新闻获悉，上海革命历史博物馆启动系列纪念活动，“红星·漫记·长征路——埃德加·斯诺与中国”主题展同于11月10日起向公众开放。展览汇集近200件展品，包括不同文字版本的《红星照耀中国》，通过斯诺与中国四十余年的交往经历为线索，让观众在具体的人物、文献与历史细节…"
