    "content": "新华社北京11月10日电 巴拿马运河管理局9日宣布，由于降雨量增加，自12日起，巴拿马运河每日通航船舶数量从33艘进一步增加至34艘。此前，受厄尔尼诺现象引发的干旱影响，巴拿马运河通航船舶数量被下调。 2025年12月29日，在巴拿马首都巴拿马城，货船通过巴拿马运河区域。新华社记者许咏政摄 法新社报道，今年由于“异常强烈的”厄尔尼诺现象导致降雨不足，巴拿马运河赖以运作的两个人工湖水位下降。巴拿马政府8月25日宣布全国进入紧急状态，以应对干旱等灾害风险及其对巴拿马运河航运等方面造成的影响。9月，巴拿马运河每日通航船舶…"
