    "description": "新华社北京11月10日电 法国柔道传奇人物、五届奥运柔道冠军特迪·里内9日宣布，将参加下一届法国总统选举。 2024年7月26日，法国男子柔道运动员特迪·里内进行火炬传递。当日，第33届夏季奥林匹克运动会在法国巴黎开幕。新华社记者杜宇摄 里内在社交媒体上发文说：“今天，我当面告诉你们，我是2027年总统选举的候选人。”他在一段时长2分37秒的视频中表示，自己担心法国可能会很快陷入严重分裂。法新社说，从发言推断，里内将自身定位在极右翼和强…",
    "content": "新华社北京11月10日电 法国柔道传奇人物、五届奥运柔道冠军特迪·里内9日宣布，将参加下一届法国总统选举。 2024年7月26日，法国男子柔道运动员特迪·里内进行火炬传递。当日，第33届夏季奥林匹克运动会在法国巴黎开幕。新华社记者杜宇摄 里内在社交媒体上发文说：“今天，我当面告诉你们，我是2027年总统选举的候选人。”他在一段时长2分37秒的视频中表示，自己担心法国可能会很快陷入严重分裂。法新社说，从发言推断，里内将自身定位在极右翼和强硬左翼政治团体之外，为选民提供替代性选择。 他表示，将很快开启竞选活动，竞选资金…"
