    "title": "四川长虹电子控股集团增资至34.3亿，增幅约14%",
    "link": "https://36kr.com/newsflashes/4063389826880647?f=rss",
    "pub_date": "2026-11-10 11:39:45",
    "author": "",
    "description": "36氪获悉，天眼查App显示，近日，四川长虹电子控股集团有限公司发生工商变更，注册资本由30亿元人民币增至约34.3亿元人民币，增幅约14%。该公司成立于1995年6月，法定代表人为柳江，经营范围包括家用电器、制冷电器及配件、照明设备、电子产品及元器件、日用电器、日用金属制品、燃气用具、电工器材的制造、销售等，由绵阳市国有资产监督管理委员会、绵阳科技城发展投资（集团）有限公司、四川省财政厅共同持股。",
    "content": "36氪获悉，天眼查App显示，近日，四川长虹电子控股集团有限公司发生工商变更，注册资本由30亿元人民币增至约34.3亿元人民币，增幅约14%。该公司成立于1995年6月，法定代表人为柳江，经营范围包括家用电器、制冷电器及配件、照明设备、电子产品及元器件、日用电器、日用金属制品、燃气用具、电工器材的制造、销售等，由绵阳市国有资产监督管理委员会、绵阳科技城发展投资（集团）有限公司、四川省财政厅共同持股。"
