    "content": "中新社北京11月10日电 (记者 张素)中国官方10日通报广东省深圳市政协原党组书记、主席戴北方涉嫌受贿一案进展。最高人民检察院依法以涉嫌受贿罪对戴北方作出逮捕决定，并指定由海南省人民检察院第一分院审查起诉。"
