    "title": "第九届进博会丨展台之外：小羊驼安家记",
    "link": "http://www.news.cn/20261110/a66543fb02fd4eeda109d06b5e09d89d/c.html",
    "pub_date": "2026-11-10 11:15:23",
    "author": "",
    "description": "进博会展台之外，一群来自新西兰的可爱羊驼和相关产品，从“四叶草”到了上海188亩的“自然卷卷牧野”，真正在中国土地扎下了根。这个牧场也填补了上海特色农牧休闲文旅的市场空白。小羊驼与新家上海实现了“双向奔赴”。 进博会的“首发效应”让“太平洋羊驼”“焕发新生”，“溢出效应”又让它“遍地开花”，不仅落地牧场，更与不同合作伙伴改进产品、升级产业链价值链。 来自新西兰的小小羊驼彻底在中国安了家。 记者：马牧旺青、蔡志坚、狄春、陈杰、孙青 新华社…",
    "content": "进博会展台之外，一群来自新西兰的可爱羊驼和相关产品，从“四叶草”到了上海188亩的“自然卷卷牧野”，真正在中国土地扎下了根。这个牧场也填补了上海特色农牧休闲文旅的市场空白。小羊驼与新家上海实现了“双向奔赴”。 进博会的“首发效应”让“太平洋羊驼”“焕发新生”，“溢出效应”又让它“遍地开花”，不仅落地牧场，更与不同合作伙伴改进产品、升级产业链价值链。 来自新西兰的小小羊驼彻底在中国安了家。 记者：马牧旺青、蔡志坚、狄春、陈杰、孙青 新华社音视频部制作"
