    "content": "新华社土耳其安塔利亚11月9日电（记者吴宝澍 王腾飞）《联合国气候变化框架公约》秘书处减缓事务主管斯泰利奥斯·佩斯马约格卢9日在联合国气候变化安塔利亚大会上表示，中国粤港澳大湾区在应对气候变化方面开展了扎实实践，取得显著成效，探索出一条绿色转型的“大湾区路径”。 佩斯马约格卢当天在大会现场“中国角”举办的广东特色展示活动中说，中国广东省稳步推进碳市场建设，探索碳足迹管理应用，扩大气候投融资规模，进一步明确绿色转型的价值导向；粤港澳大湾区同步推进适应气候变化工作，将气候适应型城市建设落到实处，并且深化跨区域协同，将大…"
