    "content": "中国官方公布的贸易数据显示，中国贸易顺差持续扩大，前十个月突破1万亿美元（约1.3万亿新元），比去年出口创纪录激增时更早达到这一数字。 中国海关总署星期二（11月10日）发布贸易数据，中国10月份出口同比大增35.2％，达到4123亿美元，推动今年首10个月的累计贸易顺差达到1.04万亿美元。"
