    "pub_date": "2026-11-10 11:03:07",
    "author": "",
    "description": "新华社哈博罗内11月9日电（记者郭春菊）博茨瓦纳总统博科9日在首都哈博罗内发表国情咨文，强调将通过有效的经济转型，扩大贸易，吸引投资，促进经济增长，改善民生。 博科说，博茨瓦纳旨在发展成为地区贸易中心，成为具有全球竞争力的投资目的地，进一步开拓包括中国在内的出口市场。 博科表示，博茨瓦纳政府将通过富有成效的经济转型，降低营商成本，提高国家金融系统效率；通过多方合作发展物流、数字技术，实现制造业本地化，稳定医药等供应链；持续反腐，打击经济…",
    "content": "新华社哈博罗内11月9日电（记者郭春菊）博茨瓦纳总统博科9日在首都哈博罗内发表国情咨文，强调将通过有效的经济转型，扩大贸易，吸引投资，促进经济增长，改善民生。 博科说，博茨瓦纳旨在发展成为地区贸易中心，成为具有全球竞争力的投资目的地，进一步开拓包括中国在内的出口市场。 博科表示，博茨瓦纳政府将通过富有成效的经济转型，降低营商成本，提高国家金融系统效率；通过多方合作发展物流、数字技术，实现制造业本地化，稳定医药等供应链；持续反腐，打击经济犯罪；大力发展职业教育，增加青年就业机会。 他说，哈博罗内机场新城等涉及改善民生…"
