    "title": "释新闻｜美国“战争部长”遭弹劾：哪八项指控？下台可能性有多大？",
    "link": "https://m.thepaper.cn/newsDetail_forward_34443239",
    "pub_date": "2026-11-10 11:00:46",
    "author": "",
    "description": "美国国防部长皮特·赫格塞思。视觉中国 资料图 当地时间11月9日，美国共和党众议员托马斯·梅西提出弹劾决议，指控美国国防部长皮特·赫格塞思违反美国联邦法律和宪法，并在多个方面滥用职权。赫格塞思最早可能在本周周中面临众议院的弹劾投票。 赫格塞思自特朗普政府2025年推动恢复“战争部长”称谓以来，一直积极使用这一称呼，并试图重塑美国军队形象。如今，他可能很快就会与美国历史上的一位战争部长拥有共同之处。1876年，美国战争部长威廉·贝尔纳普因…",
    "content": "美国国防部长皮特·赫格塞思。视觉中国 资料图 当地时间11月9日，美国共和党众议员托马斯·梅西提出弹劾决议，指控美国国防部长皮特·赫格塞思违反美国联邦法律和宪法，并在多个方面滥用职权。赫格塞思最早可能在本周周中面临众议院的弹劾投票。 赫格塞思自特朗普政府2025年推动恢复“战争部长”称谓以来，一直积极使用这一称呼，并试图重塑美国军队形象。如今，他可能很快就会与美国历史上的一位战争部长拥有共同之处。1876年，美国战争部长威廉·贝尔纳普因涉嫌收受贿赂，在众议院正式通过弹劾条款前辞职，但随后仍遭众议院弹劾，最终在参议院…"
