    "pub_date": "2026-11-10 10:58:33",
    "author": "",
    "description": "从进博会“四叶草”的展厅出来，一路向北向东。到了宝山，风里就有江的味道。 黄浦江在这里汇入长江，长江从这里入海，船从这里进出——上海的门，就在这儿。 岸上有座“水晶宫”：长滩音乐厅；还有180米高的“定海神针”观光塔。一个水晶宫，一根定海神针。老故事的想象，落在今天的江边。 登高望远，港区在眼前铺开。国际邮轮，停靠在码头。船笛一响，人就忍不住想走远一点。 今天，“爱达·花城号”、“爱达·魔都号”双双停靠吴淞口。两艘巨轮共赴江海，航线通达…",
    "content": "从进博会“四叶草”的展厅出来，一路向北向东。到了宝山，风里就有江的味道。 黄浦江在这里汇入长江，长江从这里入海，船从这里进出——上海的门，就在这儿。 岸上有座“水晶宫”：长滩音乐厅；还有180米高的“定海神针”观光塔。一个水晶宫，一根定海神针。老故事的想象，落在今天的江边。 登高望远，港区在眼前铺开。国际邮轮，停靠在码头。船笛一响，人就忍不住想走远一点。 今天，“爱达·花城号”、“爱达·魔都号”双双停靠吴淞口。两艘巨轮共赴江海，航线通达，船身巍峨，航程绵长。 进博会讲的是开放，从这里出发的船，走的也是这条路。 展馆…"
