    "content": "厦金大桥的厦门段海上主线桥顺利合龙，标志着大桥海上主线桥主体结构建设完成，项目进入通车前的收尾阶段。 据央视新闻报道，随着最后一榀钢箱梁吊装到位，厦金大桥（厦门段）海上主线桥在星期二（11月10日）凌晨顺利合龙。 此次合龙的刘五店航道东侧非通航孔桥是厦金大桥（厦门段）海上主线桥最后一个合龙桥段。桥面、机电、交安等各项配套工程施工也在加紧进行。 厦金大桥以厦门为起点，连接厦门本岛至大嶝岛，经过厦门翔安国际机场，最终目标是连接金门，因此规划分为“厦门段”与“金门段”。 据央视新闻，厦门段全长约19.6公里，包括海上主线…"
