    "description": "新华社北京11月10日电 10日，中国乒协在官网公布2026年国际乒联混合团体世界杯中国队参赛运动员名单，王楚钦、王曼昱、孙颖莎等八人入选。 中国乒协在官方通告中表示，本次名单依据国际乒联世界排名积分、近期重要国际赛事成绩，结合梯队建设与打法配备需要，确定王楚钦、林诗栋、黄友政、周启豪、王曼昱、孙颖莎、蒯曼、陈熠入选。 根据《2026年国际乒联混合团体世界杯选拔办法》，王楚钦、林诗栋、王曼昱、孙颖莎凭借单打排名（2026年10月12日国…",
