    "content": "新华社基多11月9日电 通讯：让小企业融入中国大市场——厄瓜多尔展商在进博会寻机遇 新华社记者赵鑫虎 “今年8月以来，我们已向上海发运两个集装箱，内装约10万袋炸香蕉片等产品。”厄瓜多尔休桑食品公司执行董事朱塞皮·桑切斯日前接受新华社记者采访时说，首批对华出口产品收获的积极反馈，让公司坚定了参展进博会、持续深耕中国市场的信心。 今年初，这家位于厄瓜多尔沿海地区、刚刚成立5年的食品商叩开中国市场的大门。桑切斯说：“对于小型企业而言，参加进博会就是要搭建信任纽带，为长期合作筑牢基础。” 厄瓜多尔参展方代表赴华参展前接受…"
