    "pub_date": "2026-11-10 10:32:16",
    "author": "",
    "description": "中新网11月10日电 据“泸州中院”微信公众号消息，2026年11月10日，四川省泸州市中级人民法院一审公开宣判被告人陈某芬、杨某根故意杀人，陈某芬伪造身份证件、使用虚假身份证件、偷越国(边)境暨附带民事诉讼原告人黄某提起附带民事诉讼一案，判决被告人陈某芬犯故意杀人罪、伪造身份证件罪、使用虚假身份证件罪、偷越国(边)境罪，数罪并罚，决定执行死刑，剥夺政治权利终身，并处罚金人民币二万七千元；被告人杨某根犯故意杀人罪，判处死刑，缓期二年执行…",
    "content": "中新网11月10日电 据“泸州中院”微信公众号消息，2026年11月10日，四川省泸州市中级人民法院一审公开宣判被告人陈某芬、杨某根故意杀人，陈某芬伪造身份证件、使用虚假身份证件、偷越国(边)境暨附带民事诉讼原告人黄某提起附带民事诉讼一案，判决被告人陈某芬犯故意杀人罪、伪造身份证件罪、使用虚假身份证件罪、偷越国(边)境罪，数罪并罚，决定执行死刑，剥夺政治权利终身，并处罚金人民币二万七千元；被告人杨某根犯故意杀人罪，判处死刑，缓期二年执行，剥夺政治权利终身；驳回附带民事诉讼原告人黄某的诉讼请求。"
