    "content": "中美两军在四川成都举行美军遗骸移交仪式，中方向美方移交一批在“驼峰航线”沿线区域发掘的美军援华抗日飞行员遗骸。 据央视新闻报道，仪式在星期二（11月10日）举行。报道称，搜寻美军在华失踪人员遗骸合作是”二战期间中美并肩作战、联合抗击日本法西斯历史的生动体现“。 报道还称，多年来，中方始终本着人道主义精神，协助美方搜寻相关遗骸下落。中方愿继续同美方在该领域开展务实合作，为构建中美建设性战略稳定关系增添积极因素。 今年9月24日，中国国家主席习近平访美期间，和美国总统特朗普在白宫迎宾仪式上提及中美在二战期间并肩作战的历…"
