    "content": "昨天（11月9日），随着寒潮主体南下，北方多地率先升温，今天南方也将加入升温阵营，开启回暖模式。这波回暖将持续至13日前后，中东部大部地区气温将回归较常年同期偏高水平，前后冷暖差异较大，公众需关注气温变化，适时增减衣物。今明天，我国大部降水稀少，但西南地区多阴雨，外出需带好雨具。 中东部大部逐步回暖 局地气温升幅可超15℃ 昨天，寒潮主体南下，北方多地开启升温模式，降温核心区域转移至南方。监测显示，江淮、江南、华南中东部及云南等地出现4至6℃降温，局地降幅超过8℃。 今天，寒潮影响趋于结束，中东部大部地区逐渐回暖。…"
