    "content": "美国五角大楼将中国生物科技巨企无锡药明康德从涉军中企清单剔除。 据路透社报道，美国政府星期一（11月9日）发布的公告显示，美国国防部常务副部长根据美国联邦地区法院禁止国防部执行上述认定后，作出将药明康德从涉军中企清单移除的决定。 五角大楼6月8日 扩大“中国军工企业名单” ，新增药明康德、阿里巴巴、比亚迪等多家中国企业。虽然被列入清单不代表受到制裁，但五角大楼将不得与名单上的公司签订合同，并从2027年起全面禁止通过第三方购买其产品或服务。 药明康德随后在6月11日起诉美国国防部，要求将公司名字从涉军中企名单中移除…"
