    "title": "01版 - 习近平致电祝贺约托娃当选保加利亚总统",
    "link": "http://paper.people.com.cn/rmrb/pc/content/202611/10/content_30190446.html",
    "pub_date": "2026-11-10 08:26:04",
    "author": "",
    "description": "2026年11月10日 新华社北京11月9日电 11月6日，国家主席习近平致电伊莉亚娜·约托娃，祝贺她当选保加利亚共和国总统。 习近平指出，保加利亚是世界上第二个同新中国建交的国家，相互尊重、平等相待、互利共赢是双边关系的鲜明底色。近年来，两国各层级、各领域交流合作稳步推进，战略伙伴关系内涵日益丰富。我高度重视中保关系发展，愿同约托娃总统一道努力，引领两国在各自发展振兴道路上携手前行，打造更加积极务实、富有活力的双边关系，更好造福两国人…",
