    "content": "2026年11月10日 “满目金黄，这里跟去年的荒芜景象，完全不一样了。” “再改良两年，每公顷地至少能打1.5万斤粮。” 吉林白城大安市新平安镇，空气中满是稻谷清香，收割机驶入300公顷稻田。稻浪深处，吉林省浙江商会副会长、土地承包人谢树业和跟盐碱地打了20多年交道的当地种粮大户寇金有谈起田间的收成。今年，寇金有受聘负责谢树业承包地块的田间技术管理。 大安市位于吉林省西部的一片盐碱带上，可开发利用的盐碱地规模达140余万亩，相当于全市耕地总量的近三成。但这里的盐碱地盐分重、碱化度高，是最难治理的类型之一。“风一刮…"
